testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { join } from 'node:path';
import { pegarConfiguracao, montarCaminhoDeConfig } from './solution.mjs';

test('pegarConfiguracao lê as variáveis do ambiente injetado', () => {
  assert.deepEqual(pegarConfiguracao({ MODO: 'prod', PORTA: '8080' }), { modo: 'prod', porta: 8080 });
});

test('pegarConfiguracao usa os padrões quando as variáveis não existem', () => {
  assert.deepEqual(pegarConfiguracao({}), { modo: 'dev', porta: 3000 });
});

test('lança erro em entradas inválidas', () => {
  assert.throws(() => pegarConfiguracao({ PORTA: 'abc' }), /número/);
  assert.throws(() => montarCaminhoDeConfig({ HOME: '/home/ana' }, 42), /string/);
});

test('montarCaminhoDeConfig monta o caminho com path.join', () => {
  const caminho = montarCaminhoDeConfig({ HOME: '/home/ana' }, 'app');
  assert.equal(caminho, join('/home/ana', '.config', 'app', 'config.json'));
});

solutionCode:
import { join } from 'node:path';

export function pegarConfiguracao(env) {
  if (!env || typeof env !== 'object') {
    throw new Error('env precisa ser um objeto');
  }

  const porta = Number(env.PORTA ?? 3000);
  if (Number.isNaN(porta)) {
    throw new Error('PORTA precisa ser um número');
  }

  return {
    modo: env.MODO ?? 'dev',
    porta,
  };
}

export function montarCaminhoDeConfig(env, projeto) {
  if (typeof projeto !== 'string') {
    throw new Error('projeto precisa ser uma string');
  }

  const casa = env && typeof env.HOME === 'string' ? env.HOME : '.';
  return join(casa, '.config', projeto, 'config.json');
}
